CREATE TABLE assets_frozen(workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE assets_maintenance_bypass(workspace_id TEXT NOT NULL, PRIMARY KEY(workspace_id));
CREATE TABLE assets_uploads(workspace_id TEXT NOT NULL, id TEXT NOT NULL, asset_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,asset_id) REFERENCES assets_blobs(workspace_id,id));
ALTER TABLE assets_events ADD COLUMN project_id TEXT;
ALTER TABLE assets_receipts ADD COLUMN project_id TEXT;
UPDATE assets_events SET project_id=(SELECT project_id FROM assets_blobs WHERE workspace_id=assets_events.workspace_id AND id=assets_events.aggregate_id);
UPDATE assets_receipts SET project_id=(SELECT project_id FROM assets_blobs WHERE workspace_id=assets_receipts.workspace_id AND id=assets_receipts.result_id);
CREATE TRIGGER assets_events_project AFTER INSERT ON assets_events BEGIN UPDATE assets_events SET project_id=(SELECT project_id FROM assets_blobs WHERE workspace_id=NEW.workspace_id AND id=NEW.aggregate_id) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER assets_receipts_project AFTER INSERT ON assets_receipts BEGIN UPDATE assets_receipts SET project_id=(SELECT project_id FROM assets_blobs WHERE workspace_id=NEW.workspace_id AND id=NEW.result_id) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER assets_blobs_freeze_insert BEFORE INSERT ON assets_blobs WHEN NOT EXISTS(SELECT 1 FROM assets_maintenance_bypass WHERE workspace_id=NEW.workspace_id) AND EXISTS(SELECT 1 FROM assets_frozen WHERE workspace_id=NEW.workspace_id AND (project_id='' OR project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: assets scope frozen'); END;
CREATE TRIGGER assets_blobs_freeze_update BEFORE UPDATE ON assets_blobs WHEN NOT EXISTS(SELECT 1 FROM assets_maintenance_bypass WHERE workspace_id=NEW.workspace_id) AND EXISTS(SELECT 1 FROM assets_frozen WHERE workspace_id=NEW.workspace_id AND (project_id='' OR project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: assets scope frozen'); END;
CREATE TRIGGER assets_blobs_freeze_delete BEFORE DELETE ON assets_blobs WHEN NOT EXISTS(SELECT 1 FROM assets_maintenance_bypass WHERE workspace_id=OLD.workspace_id) AND EXISTS(SELECT 1 FROM assets_frozen WHERE workspace_id=OLD.workspace_id AND (project_id='' OR project_id=OLD.project_id)) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: assets scope frozen'); END;
