CREATE TRIGGER assets_receipts_freeze_insert BEFORE INSERT ON assets_receipts WHEN NOT EXISTS(SELECT 1 FROM assets_maintenance_bypass WHERE workspace_id=NEW.workspace_id) AND EXISTS(SELECT 1 FROM assets_frozen WHERE workspace_id=NEW.workspace_id AND (project_id='' OR project_id=COALESCE(NEW.project_id,(SELECT project_id FROM assets_blobs WHERE workspace_id=NEW.workspace_id AND id=NEW.result_id)))) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: assets scope frozen'); END;
